def normalize_value(v):
    """Flatten singleSelect objects to name strings, multipleSelects arrays to string arrays."""
    if isinstance(v, dict) and "name" in v and "id" in v and str(v["id"]).startswith("sel"):
        return v["name"]
    if isinstance(v, list):
        result = []
        for item in v:
            if isinstance(item, dict) and "name" in item and "id" in item and str(item["id"]).startswith("sel"):
                result.append(item["name"])
            else:
                result.append(item)
        return result
    return v

def normalize_record(rec):
    fields = rec.get("cellValuesByFieldId", {})
    normalized_fields = {k: normalize_value(v) for k, v in fields.items()}
    return {"id": rec["id"], "fields": normalized_fields}

